/**
 * Up command handler
 */
import { parseUpArgs, upCommand } from "./command.js";
import { showLogo } from "../../utils/index.js";
import { parseArgsOrThrow } from "../../shared/args.js";
import { ensureCliBundlerContracts } from "../../shared/default-contracts.js";
const defaultDependencies = {
    ensureBundlerContracts: ensureCliBundlerContracts,
    up: upCommand,
};
export async function handleUpCommand(args, dependencies = defaultDependencies) {
    showLogo();
    const options = parseArgsOrThrow(parseUpArgs, "up", args);
    await dependencies.ensureBundlerContracts();
    await dependencies.up(options);
}
